SourceCode.Declaration:
/// <summary>
/// CB434 - Mirrors InventItemPriceActivationTasksBuilder but produces
/// METInventItemPriceActivationByGUPTask bundles from GUPItemBasePrice records.
/// </summary>
class METInventItemPriceActivationByGUPTasksBuilder
{
    List                                        tasks;
    METInventItemPriceActivationByGUPTask       task;
    int                                         processedCount;
    InventItemPriceActivationBundleSize         bundleSize;

}

Method.Source:
protected void new()
{
    tasks      = new List(Types::Class);
    bundleSize = 40;
}

public METInventItemPriceActivationByGUPTasksBuilder addGUPItemBasePrice(GUPItemBasePrice _basePrice)
{
    if (processedCount mod bundleSize == 0)
    {
        task = METInventItemPriceActivationByGUPTask::construct();
        tasks.addEnd(task);
    }
    processedCount++;
    task.addGUPItemBasePrice(_basePrice);
    return this;
}
